/*
Theme Name: FORME HOME Demo
Theme URI: https://beqson.com/
Author: BEQSON Digital Studio
Description: Premium editorial WooCommerce showcase. Demo only; no payments.
Version: 1.0.0
Text Domain: forme-home
*/
:root{--ink:#292825;--muted:#77756f;--linen:#f8f7f3;--sand:#eae6df;--line:#e1ddd6;--green:#677264;--accent:#b9906a;--white:#fff;--max:1240px}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--linen);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;-webkit-font-smoothing:antialiased;font-size:15px;line-height:1.6}a{color:inherit;text-decoration:none}img{max-width:100%;display:block}button,input,select,textarea{font:inherit}button,a{transition:opacity .2s,transform .2s}button:hover,.btn:hover{transform:translateY(-1px)}button{cursor:pointer}
.wrap{width:min(var(--max),calc(100% - 64px));margin:auto}
.top-note{background:#353b36;color:#f8f5ef;text-align:center;font-size:11px;letter-spacing:.12em;text-transform:uppercase;padding:9px 12px}
.site-header{background:rgba(248,247,243,.96);position:sticky;top:0;z-index:90;border-bottom:1px solid var(--line);backdrop-filter:blur(14px)}
.nav{min-height:83px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.brand{display:flex;align-items:center;gap:12px;font-family:Georgia,serif;font-size:28px;letter-spacing:.14em;line-height:1}
.brand-mark{width:29px;height:29px;border:1px solid #8c927c;border-radius:50%;display:grid;place-items:center;color:#8c927c;font:16px Georgia,serif}
.brand-sub{font:9px Arial,sans-serif;letter-spacing:.3em;color:#85837b;margin-top:7px}
.nav-links{display:flex;align-items:center;gap:30px;font-size:12px;letter-spacing:.07em;text-transform:uppercase}
.nav-icons{display:flex;align-items:center;gap:22px;font-size:12px}.nav-icons .bag{position:relative;font-size:22px}.count{position:absolute;background:#566552;color:white;border-radius:50%;font:10px Arial;min-width:17px;height:17px;text-align:center;padding:2px;top:-6px;right:-12px}
.demo-ribbon{background:#e8e5dc;color:#615f5a;padding:9px;text-align:center;font-size:11px;letter-spacing:.02em}.demo-ribbon strong{font-weight:700}
.eyebrow{font:11px Arial,sans-serif;letter-spacing:.2em;text-transform:uppercase;color:var(--green);font-weight:600}.eyebrow.light{color:#e3d9bf}
h1,h2,h3,.serif{font-family:Georgia,"Times New Roman",serif;font-weight:400;letter-spacing:-.045em;line-height:1.12}h1{font-size:clamp(49px,6.3vw,93px);margin:19px 0 28px}h2{font-size:clamp(36px,4vw,58px);margin:14px 0 24px}h3{font-size:27px;margin:12px 0}.lead{font-size:16px;color:#77766e;line-height:1.85;max-width:440px}.btn{display:inline-flex;align-items:center;gap:32px;justify-content:center;background:#343f35;color:white;padding:17px 27px;font-size:12px;letter-spacing:.12em;text-transform:uppercase;border:0}.btn.alt{background:transparent;border:1px solid #6e756b;color:#343f35}
.hero{position:relative;min-height:650px;display:grid;grid-template-columns:43% 57%;background:#edeae3}.hero-copy{padding:70px 8% 80px max(28px,calc((100vw - 1240px)/2));align-self:center}.hero-copy .lead{margin-bottom:35px}.hero-photo{background:#bfb6a9 url('https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=1600&q=85') center 55%/cover no-repeat;position:relative}.hero-photo:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#edeae3 0%,rgba(237,234,227,0) 20%)}.hero-stamp{position:absolute;bottom:36px;right:35px;color:white;border:1px solid rgba(255,255,255,.7);padding:15px 22px;letter-spacing:.2em;font-size:10px;text-transform:uppercase}
.features{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--line);gap:18px;padding:26px 0}.features>div{display:flex;gap:18px;align-items:center;justify-content:center;font-size:12px;color:var(--muted)}.features b{font-weight:500;color:var(--ink)}.features .num{font:28px Georgia;color:#a09b89}
.section{padding:90px 0}.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:36px}.section-head p{max-width:370px;color:var(--muted);font-size:14px}.text-link{font-size:11px;letter-spacing:.12em;text-transform:uppercase;border-bottom:1px solid;padding-bottom:6px;white-space:nowrap}
.cat-grid{display:grid;grid-template-columns:1.18fr 1fr 1fr;gap:20px}.cat-tile{background:#e1ddd4;position:relative;min-height:360px;overflow:hidden}.cat-tile:first-child{min-height:530px}.cat-tile img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0;transition:transform .6s}.cat-tile:hover img{transform:scale(1.035)}.cat-tile:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(26,31,26,.55),transparent 55%)}.cat-copy{position:absolute;bottom:25px;left:28px;right:24px;z-index:2;color:white}.cat-copy span{display:block;font-size:10px;letter-spacing:.2em;text-transform:uppercase}.cat-copy h3{font-size:35px;margin:5px 0}
.product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.product-card{min-width:0}.product-img{aspect-ratio:4/4.8;position:relative;display:block;background:#e9e5dd;overflow:hidden}.product-img img{width:100%;height:100%;object-fit:cover;transition:transform .55s}.product-img:hover img{transform:scale(1.055)}.product-badge{position:absolute;top:14px;left:14px;background:#f9f7f2;color:#5c6258;padding:7px 10px;font-size:10px;letter-spacing:.08em}.product-info{padding:16px 0 6px;display:flex;justify-content:space-between;gap:10px}.product-info strong{display:block;font:20px Georgia,serif;font-weight:400;line-height:1.2}.product-info .small{font-size:11px;color:#9b968f;margin-top:6px}.price{white-space:nowrap;font-size:13px}.price del{opacity:.45;font-size:11px;margin-right:6px}.price ins{text-decoration:none}.quick-add{border:1px solid var(--line);display:inline-block;color:#3d423b;font-size:10px;letter-spacing:.09em;text-transform:uppercase;padding:9px 12px;margin-top:8px;background:transparent}.quick-add:hover{background:#384037;color:white}
.story{background:#e7e5dc;display:grid;grid-template-columns:50% 50%;min-height:500px}.story-art{background:url('https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?w=1400&q=85') center/cover no-repeat}.story-copy{padding:90px max(30px,calc((100vw - 1240px)/2)) 70px 9%;align-self:center}.story-copy p{max-width:460px;color:#77746a;line-height:1.8}.story .btn{margin-top:22px}
.newsletter{border-top:1px solid var(--line);padding:75px 0;text-align:center}.newsletter h2{margin-bottom:14px}.newsletter p{color:var(--muted);font-size:14px}
.page-title{padding:68px 0 42px;text-align:center}.page-title h1{font-size:clamp(42px,5vw,70px);margin:14px auto}.page-title p{color:var(--muted)}.shop-wrap{padding-bottom:100px}
.woocommerce-result-count,.woocommerce-ordering{font-size:13px;color:#777}.woocommerce-ordering select{background:transparent;padding:10px;border:1px solid var(--line)}
.woocommerce ul.products{display:grid!important;grid-template-columns:repeat(4,1fr);gap:20px;padding:0!important;list-style:none}.woocommerce ul.products:before,.woocommerce ul.products:after{display:none!important}.woocommerce ul.products li.product{float:none!important;width:100%!important;margin:0!important;padding:0!important}.woocommerce ul.products li.product a.woocommerce-loop-product__link{display:block}.woocommerce nav.woocommerce-pagination{margin:46px auto}
.single-grid{display:grid;grid-template-columns:57% 43%;gap:70px;padding:40px 0 100px}.single-photo{background:#e6e2db;min-height:560px;max-height:760px}.single-photo img{width:100%;height:100%;object-fit:cover}.single-summary{padding-top:22px}.single-summary h1{font-size:clamp(36px,4vw,60px);line-height:1.1;margin:12px 0 22px}.single-summary .price{font-size:24px;display:block;margin-bottom:27px}.single-summary p{color:#77756d}.single-summary .cart{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:26px 0}.single-summary .quantity input{width:69px;padding:12px;border:1px solid var(--line);background:white}.single-summary .single_add_to_cart_button{background:#343f35!important;color:#fff!important;border:0!important;padding:16px 27px!important;letter-spacing:.08em!important}.single-summary .product_meta{font-size:12px;line-height:2.4;color:#888}
.single-summary .woocommerce-product-details__short-description{line-height:1.85}.single-features{border-top:1px solid var(--line);margin-top:30px;padding-top:18px;font-size:12px;color:#7a786f}.single-features div{padding:9px 0}
.content-page{min-height:48vh;padding:40px 0 120px;max-width:930px}.content-page h1{font-size:55px}.woocommerce .button,.woocommerce button.button,.woocommerce input.button{background:#3c483d!important;color:white!important;border-radius:0!important;padding:14px 20px!important;font-size:12px!important;letter-spacing:.04em}.woocommerce input.input-text,.woocommerce textarea,.woocommerce select{padding:12px;border:1px solid #ddd7cd;background:#fff;border-radius:0}.woocommerce table.shop_table{border:1px solid var(--line);border-radius:0}.woocommerce-message,.woocommerce-info{border-top-color:#647461}.woocommerce a{color:#586951}
.site-footer{background:#343d35;color:#eeeae0;padding:68px 0 18px}.footer-main{display:grid;grid-template-columns:2fr 1fr 1fr;gap:35px;border-bottom:1px solid rgba(255,255,255,.2);padding-bottom:55px}.site-footer .brand{color:white}.site-footer p{color:#c5c9bf;font-size:13px;max-width:300px}.site-footer a{display:block;font-size:13px;margin:9px 0;color:#daddd4}.site-footer .eyebrow{color:#a7b3a2}.footer-last{display:flex;justify-content:space-between;gap:25px;color:#c3c7be;font-size:11px;padding-top:20px}
@media(max-width:960px){.hero{grid-template-columns:1fr 1fr;min-height:560px}.hero-copy{padding:60px 35px}.product-grid,.woocommerce ul.products{grid-template-columns:repeat(3,1fr)!important}.single-grid{gap:30px}.cat-grid{grid-template-columns:1fr 1fr}.cat-tile:first-child{min-height:360px;grid-column:span 2}.story-copy{padding:60px 35px}}
@media(max-width:650px){.wrap{width:calc(100% - 32px)}.nav{min-height:68px}.brand{font-size:22px}.nav-links{display:none}.top-note{font-size:9px}.hero{display:flex;flex-direction:column-reverse}.hero-photo{height:330px;min-height:330px}.hero-photo:after{background:none}.hero-copy{padding:44px 23px 55px}.hero h1{font-size:57px}.hero-stamp{bottom:15px;right:15px;padding:9px;font-size:8px}.features{grid-template-columns:1fr;gap:13px}.features>div{justify-content:flex-start}.section{padding:60px 0}.section-head{display:block}.cat-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.cat-tile,.cat-tile:first-child{min-height:260px}.cat-tile:first-child{grid-column:span 2}.cat-copy h3{font-size:27px}.cat-copy{left:15px;bottom:12px}.product-grid,.woocommerce ul.products{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px}.product-info{display:block}.product-info strong{font-size:17px}.price{font-size:12px}.quick-add{font-size:9px;padding:8px}.story{display:flex;flex-direction:column}.story-art{min-height:320px}.story-copy{padding:52px 26px}.single-grid{display:block;padding:12px 0 50px}.single-photo{min-height:0;aspect-ratio:4/4.5}.single-summary{padding-top:30px}.page-title{padding:45px 0 25px}.page-title h1,.content-page h1{font-size:44px}.footer-main{grid-template-columns:1fr 1fr}.footer-main>div:first-child{grid-column:span 2}.footer-last{display:block}.footer-last span{display:block;margin:10px 0}}
